// Route the run. "Customer Binding" / "Supplier Binding" take the new bind path
// below; anything else -- including a dialog that predates this field -- falls
// through untouched to the original price flow (nodes 1-8).
const formData = {{workflowparams:data}};
const dialog = (formData && formData.dialog_update) || {};
const updateType =
  dialog.update_type === undefined || dialog.update_type === null
    ? ""
    : String(dialog.update_type).trim();

const isCustomer = updateType.toLowerCase() === "customer binding";
const isSupplier = updateType.toLowerCase() === "supplier binding";

return {
  updateType: updateType,
  isBinding: isCustomer || isSupplier,
  isCustomer: isCustomer,
};

// Read the uploaded rows for a binding run and collect the distinct lookup keys
// the parallel searches need. Column names differ per family, and "Item Code" is
// new here: the in-form importers (ItemCustBindImport.js / ItemSupBindImport.js)
// are scoped to the single item being edited, this one spans many.
const formData = {{workflowparams:data}};
const isCustomer = {{node:code_node_updType.data.isCustomer}};
const updateFile =
  (formData && formData.dialog_update && formData.dialog_update.update_file) ||
  {};

const str = (v) => (v === undefined || v === null ? "" : String(v).trim());

const COL_CODE = isCustomer ? "Customer Code" : "Supplier Code";
const COL_NAME = isCustomer ? "Customer Name" : "Supplier Name";
const COL_ALIAS = isCustomer ? "Customer Item Alias" : "Supplier Item Alias";
const COL_DESC = "Item Description";

// Never feed an empty array into an equalAny filter; a "0" sentinel matches nothing.
const fail = (message) => ({
  isValid: false,
  message: message,
  rows: [],
  itemCodes: ["0"],
  partyCodes: ["0"],
  partyNames: ["0"],
});

// Cap the listed problems so the dialog stays readable.
const formatErrors = (list) => {
  const shown = list.slice(0, 15).join(" ");
  return list.length > 15
    ? shown + " ... and " + (list.length - 15) + " more."
    : shown;
};

const numericKeys = Object.keys(updateFile).filter((k) => !isNaN(parseInt(k)));
if (numericKeys.length === 0) {
  return fail("No valid data rows found in the uploaded file.");
}

// Header check on the first data row, mirroring "1. Check File Input".
const firstRow = updateFile[numericKeys[0]] || {};
const missing = [];
if (!("Item Code" in firstRow)) missing.push("Item Code");
if (!(COL_CODE in firstRow) && !(COL_NAME in firstRow)) {
  missing.push(COL_CODE + " or " + COL_NAME);
}
if (!(COL_ALIAS in firstRow) && !(COL_DESC in firstRow)) {
  missing.push(COL_ALIAS + " or " + COL_DESC);
}
if (missing.length > 0) {
  return fail("These columns are missing: " + missing.join(", "));
}

const rows = [];
const errors = [];
const itemCodes = [];
const partyCodes = [];
const partyNames = [];

numericKeys
  .map((k) => parseInt(k, 10))
  .sort((a, b) => a - b)
  .forEach((k) => {
    const raw = updateFile[k] || {};
    const itemCode = str(raw["Item Code"]);
    const code = str(raw[COL_CODE]);
    const name = str(raw[COL_NAME]);
    const alias = str(raw[COL_ALIAS]);
    const desc = str(raw[COL_DESC]);

    // Trailing blank spreadsheet rows are ignored, not reported.
    if (!itemCode && !code && !name && !alias && !desc) return;

    // The parser consumes line 1 as the header row, so data index 0 is line 2.
    const label = "Excel row " + (k + 2);
    if (!itemCode) {
      errors.push(label + ": Item Code is required.");
      return;
    }
    if (!code && !name) {
      errors.push(label + ": " + COL_CODE + " or " + COL_NAME + " is required.");
      return;
    }
    if (!alias && !desc) {
      errors.push(
        label + ": " + COL_ALIAS + " or " + COL_DESC + " is required.",
      );
      return;
    }

    rows.push({
      label: label,
      itemCode: itemCode,
      code: code,
      name: name,
      alias: alias,
      desc: desc,
    });

    if (itemCodes.indexOf(itemCode) === -1) itemCodes.push(itemCode);
    if (code) {
      if (partyCodes.indexOf(code) === -1) partyCodes.push(code);
    } else if (partyNames.indexOf(name) === -1) {
      partyNames.push(name);
    }
  });

if (errors.length > 0) {
  return fail("The file was not imported. " + formatErrors(errors));
}
if (rows.length === 0) {
  return fail("No valid data rows found in the uploaded file.");
}

if (itemCodes.length === 0) itemCodes.push("0");
if (partyCodes.length === 0) partyCodes.push("0");
if (partyNames.length === 0) partyNames.push("0");

return {
  isValid: true,
  message: "",
  rows: rows,
  itemCodes: itemCodes,
  partyCodes: partyCodes,
  partyNames: partyNames,
};

// Resolve item codes and partners, then upsert the file's rows into each item's
// EXISTING bind array. A parent fetch returns subform array columns inline (see
// GlobalAllocationWorkflow / PPheadWorkflow reading itemData.table_uom_conversion),
// so no second lookup is needed to read what is already bound.
const isCustomer = {{node:code_node_updType.data.isCustomer}};
const rows = {{node:code_node_bindMap.data.rows}} || [];
const itemData = {{node:search_node_bindItem.data.data}} || [];
const custData = {{node:search_node_bindCust.data.data}} || [];
const supData = {{node:search_node_bindSup.data.data}} || [];

const str = (v) => (v === undefined || v === null ? "" : String(v).trim());
const lc = (v) => str(v).toLowerCase();

// The two families differ by SIX key names and every way of getting them wrong
// fails silently (the lookup just never matches). They are named once, here.
const partyData = isCustomer ? custData : supData;
const PARTY = isCustomer ? "Customer" : "Supplier";
const BIND_COL = isCustomer ? "table_cust_item_bind" : "table_sup_item_bind";
const F_ID = isCustomer ? "customer_id" : "supplier_id";
const F_NAME = isCustomer ? "customer_name" : "supplier_name";
const F_ALIAS = isCustomer ? "cust_item_alias" : "sup_item_alias";
const F_DESC = isCustomer ? "item_desc" : "item_description";
// Customer's code lives in customer_id; Supplier's lives in supplier_code.
const P_CODE = isCustomer ? "customer_id" : "supplier_code";
const P_NAME = isCustomer ? "customer_com_name" : "supplier_com_name";
const P_STATUS = isCustomer ? "customer_status" : "supplier_status";

const formatErrors = (list) => {
  const shown = list.slice(0, 15).join(" ");
  return list.length > 15
    ? shown + " ... and " + (list.length - 15) + " more."
    : shown;
};

// equalAny is case-insensitive, so key the maps the same way.
const itemByCode = {};
itemData.forEach((it) => {
  const k = lc(it.material_code);
  if (!k) return;
  if (!itemByCode[k]) itemByCode[k] = [];
  itemByCode[k].push(it);
});

const partyByCode = {};
const partyByName = {};
partyData.forEach((p) => {
  if (p.is_deleted === 1) return;
  const k1 = lc(p[P_CODE]);
  const k2 = lc(p[P_NAME]);
  if (k1) {
    if (!partyByCode[k1]) partyByCode[k1] = [];
    partyByCode[k1].push(p);
  }
  if (k2) {
    if (!partyByName[k2]) partyByName[k2] = [];
    partyByName[k2].push(p);
  }
});

const errors = [];
const resolved = [];

rows.forEach((r) => {
  const items = itemByCode[lc(r.itemCode)] || [];
  if (items.length === 0) {
    errors.push(r.label + ': Item Code "' + r.itemCode + '" not found.');
    return;
  }
  if (items.length > 1) {
    errors.push(
      r.label +
        ': Item Code "' +
        r.itemCode +
        '" matches ' +
        items.length +
        " items.",
    );
    return;
  }

  const useCode = r.code !== "";
  const identifier = useCode ? r.code : r.name;
  const matches =
    (useCode ? partyByCode[lc(r.code)] : partyByName[lc(r.name)]) || [];

  if (matches.length === 0) {
    errors.push(
      r.label +
        ": " +
        PARTY +
        " " +
        (useCode ? "Code" : "Name") +
        ' "' +
        identifier +
        '" not found.',
    );
    return;
  }
  if (matches.length > 1) {
    errors.push(
      r.label +
        ": " +
        PARTY +
        " " +
        (useCode ? "Code" : "Name") +
        ' "' +
        identifier +
        '" matches ' +
        matches.length +
        " records" +
        (useCode ? "." : ". Use the " + PARTY + " Code instead."),
    );
    return;
  }

  const party = matches[0];
  if (str(party[P_STATUS]) !== "Active") {
    errors.push(
      r.label +
        ": " +
        PARTY +
        ' "' +
        identifier +
        '" is not Active (status: ' +
        (str(party[P_STATUS]) || "-") +
        ").",
    );
    return;
  }

  resolved.push({ item: items[0], party: party, alias: r.alias, desc: r.desc });
});

if (errors.length > 0) {
  return {
    status: "Failed",
    message: "Nothing was updated. " + formatErrors(errors),
    itemUpdates: [],
  };
}

// Group by item so each item is written exactly once, preserving file order.
const byItemId = {};
const order = [];
resolved.forEach((r) => {
  const id = String(r.item.id);
  if (!byItemId[id]) {
    byItemId[id] = { item: r.item, entries: [] };
    order.push(id);
  }
  byItemId[id].entries.push(r);
});

// Row identity is partner + alias, so one partner keeps several rows (different
// pack/spec per alias). Bindings the file does not mention are left untouched.
const keyOf = (partyId, alias) => String(partyId) + "|" + lc(alias);

const itemUpdates = order.map((id) => {
  const bucket = byItemId[id];
  const existing = Array.isArray(bucket.item[BIND_COL])
    ? bucket.item[BIND_COL].slice()
    : [];

  const index = {};
  existing.forEach((row, i) => {
    index[keyOf(row[F_ID], row[F_ALIAS])] = i;
  });

  bucket.entries.forEach((e) => {
    const k = keyOf(e.party.id, e.alias);
    const at = index[k];
    const prev = at === undefined ? null : existing[at];

    const row = {};
    row[F_ID] = e.party.id;
    row[F_NAME] = str(e.party[P_NAME]);
    row[F_ALIAS] = e.alias;
    // A blank description cell keeps what is already there -- same fallback
    // semantics as the price path's toPrice(primary, fallback).
    row[F_DESC] = e.desc !== "" ? e.desc : prev ? str(prev[F_DESC]) : "";

    if (at === undefined) {
      index[k] = existing.length;
      existing.push(row);
    } else {
      existing[at] = row;
    }
  });

  return { id: bucket.item.id, bindRows: existing };
});

return {
  status: "Success",
  message: "Updated " + itemUpdates.length + " item(s).",
  itemUpdates: itemUpdates,
};

const formData = {{workflowparams:data}};

const requiredFields = [
  "Item Code",
  "UOM",
];

// Get only the numeric keys (actual data rows)
const updateFile = formData.dialog_update.update_file;
const numericKeys = Object.keys(updateFile).filter(
  (key) => !isNaN(parseInt(key)),
);

if (numericKeys.length === 0) {
  return {
    isValid: false,
    message: "No valid numeric keys found in update_file",
  };
}

// Check required fields exist in the first item
const firstItem = updateFile[numericKeys[0]];
const missingFields = [];

for (const field of requiredFields) {
  if (!(field in firstItem)) {
    missingFields.push(field);
  }
}

if (missingFields.length > 0) {
  return {
    isValid: false,
    message: "These fields are missing: " + missingFields.join(","),
  };
}

return {
  isValid: true,
  message: "All validations passed",
};

const formData = {{workflowparams:data.dialog_update.update_file}};

return {
  updatedData: Object.keys(formData)
    .filter((key) => !isNaN(parseInt(key)))
    .map((key) => {
      const item = formData[key];
      return {
        material_code: item["Item Code"],
        uom_name: item["UOM"],
        purchase_unit_price: item["Purchase Unit Price"],
        sales_unit_price: item["Sales Unit Price"],
        purchase_tax: item["Purchase Tax"],
        sales_tax: item["Sales Tax"],
        purchase_tax_percent: item["Purchase Tax %"],
        sales_tax_percent: item["Sales Tax %"],
        purchase_min_price: item["Purchase Min Price"],
        purchase_max_price: item["Purchase Max Price"],
        sales_min_price: item["Sales Min Price"],
        sales_max_price: item["Sales Max Price"],
        sales_price_1: item["Sales Price 1"],
        sales_price_2: item["Sales Price 2"],
        sales_price_3: item["Sales Price 3"],
        sales_price_4: item["Sales Price 4"],
        sales_price_5: item["Sales Price 5"],
        sales_price_6: item["Sales Price 6"],
      };
    }),
};

const updatedData = {{node:code_node_h0nbfgRx.data.updatedData}};
const itemData = {{node:search_node_m9ws9ASy.data.data}};
const uomData = {{node:search_node_vNAH9LEk.data.data}};
const taxData = {{node:search_node_Pv9Bxnth.data.data}};
const uomConversionData = {{node:search_node_AkGvE8Wx.data.data}};

// Use the item's value only when it parses to a real number; otherwise fall
// back to the master (UOM conversion) value. Prevents a blank/garbage cell
// (e.g. "NaN", "abc") from surviving the `||` and producing "NaN".
const toPrice = (primary, fallback) => {
  let value = parseFloat(primary);
  if (Number.isNaN(value)) value = parseFloat(fallback);
  return Number.isNaN(value) ? "0.0000" : value.toFixed(4);
};

const updatedItemData = updatedData.map((item) => {
  const matchedItemData = itemData.find(i => i.material_code === item.material_code);
  const matchedUOMData = uomData.find(i => i.uom_name === item.uom_name);
  const matchedUOMConversionData = uomConversionData.find(i => i.alt_uom_id === matchedUOMData.id && i.Item_id === matchedItemData.id);
  const matchedPurchaseTax = taxData.find(i => i.tax_code === item.purchase_tax);
  const matchedSalesTax = taxData.find(i => i.tax_code === item.sales_tax);

  return {
    ...item,
    id: matchedUOMConversionData ? matchedUOMConversionData.id : null,
    purchase_unit_price: toPrice(item.purchase_unit_price, matchedUOMConversionData.purchase_unit_price),
    sales_unit_price: toPrice(item.sales_unit_price, matchedUOMConversionData.sales_unit_price),
    mat_purchase_tax_id: matchedPurchaseTax ? matchedPurchaseTax.id : matchedUOMConversionData.mat_purchase_tax_id,
    purchase_max_price: toPrice(item.purchase_max_price, matchedUOMConversionData.purchase_max_price),
    purchase_min_price: toPrice(item.purchase_min_price, matchedUOMConversionData.purchase_min_price),
    purchase_tax_percent: item.purchase_tax_percent ?? matchedUOMConversionData.purchase_tax_percent,
    sales_max_price: toPrice(item.sales_max_price, matchedUOMConversionData.sales_max_price),
    sales_min_price: toPrice(item.sales_min_price, matchedUOMConversionData.sales_min_price),
    mat_sales_tax_id: matchedSalesTax ? matchedSalesTax.id : matchedUOMConversionData.mat_sales_tax_id,
    sales_tax_percent: item.sales_tax_percent ?? matchedUOMConversionData.sales_tax_percent,
    sales_price_1: toPrice(item.sales_price_1, matchedUOMConversionData.sales_price_1),
    sales_price_2: toPrice(item.sales_price_2, matchedUOMConversionData.sales_price_2),
    sales_price_3: toPrice(item.sales_price_3, matchedUOMConversionData.sales_price_3),
    sales_price_4: toPrice(item.sales_price_4, matchedUOMConversionData.sales_price_4),
    sales_price_5: toPrice(item.sales_price_5, matchedUOMConversionData.sales_price_5),
    sales_price_6: toPrice(item.sales_price_6, matchedUOMConversionData.sales_price_6),
  }
})

const missingUOMs = updatedItemData
  .filter(item => !item.id)
  .map(item => `${item.material_code} (${item.uom_name})`);

if(missingUOMs.length > 0) {
  return {
    status: 'Failed',
    message: `These record cannot be found: ${missingUOMs.join(', ')}`,
    updatedItemData: missingUOMs
  }
}

return {
  status: 'Success',
  message: 'All items validated successfully',
  updatedItemData: updatedItemData
}
